#requires -Version 5.1
param([Parameter(Mandatory=$true)][ValidateSet('install','remove')][string]$Action,[Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Data)
$ErrorActionPreference='Stop'
# Service creation remains exclusively the vendor's service-only installer.
function Full([string]$p){
 if($p -notmatch '^[A-Za-z]:[\\/]'){throw 'An absolute local path is required'}
 [IO.Path]::GetFullPath($p).TrimEnd('\')
}
function Under([string]$p,[string]$base){$p.StartsWith(($base+'\'),[StringComparison]::OrdinalIgnoreCase)}
function Assert-Plain([string]$p){
 $p=Full $p
 while($p){
  if(Test-Path -LiteralPath $p){if((Get-Item -LiteralPath $p -Force).Attributes -band [IO.FileAttributes]::ReparsePoint){throw ('Unexpected reparse point: '+$p)}}
  $parent=Split-Path -Parent $p
  if(!$parent -or $parent -eq $p){break};$p=$parent
 }
}
function Digest([string]$path){
 $stream=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read)
 $sha=[Security.Cryptography.SHA256]::Create()
 try{[BitConverter]::ToString($sha.ComputeHash($stream))}finally{$sha.Dispose();$stream.Dispose()}
}
$Root=Full $Root
$package=Split-Path -Parent $Root
$pikoHome=Split-Path -Parent (Split-Path -Parent $package)
Assert-Plain $Root
if((Full $PSScriptRoot) -ine $Root){throw 'Script must run from its own real version directory'}
function Read-Install([string]$dir){
 Assert-Plain $dir
 Assert-Plain (Join-Path $dir '.piko-install.json')
 $r=Get-Content -LiteralPath (Join-Path $dir '.piko-install.json') -Raw|ConvertFrom-Json
 if($r.name -cne 'sunlogin' -or $r.kind -cne 'portable' -or $r.verified -ne $true -or !$r.id -or !$r.key -or !$r.source.identity -or $r.checksum -notmatch '^[a-fA-F0-9]{64}$' -or $r.manifestHash -notmatch '^[a-fA-F0-9]{64}$'){throw 'Invalid Sunlogin installation receipt'}
 if([IO.Path]::IsPathRooted($r.dir) -or (Full (Join-Path $pikoHome $r.dir)) -ine $dir -or (Split-Path -Parent $dir) -ine $package){throw 'Installation receipt path mismatch'}
 $r
}
$install=Read-Install $Root
$folder=if($install.layout -eq 'named-v1'){'sunlogin'}else{$install.key}
if($package -ine (Full (Join-Path (Join-Path $pikoHome 'apps') $folder))){throw 'Unexpected Sunlogin package directory'}
$Data=Full $Data
if($Data -ine (Full (Join-Path (Join-Path (Join-Path $pikoHome 'persist') $folder) '.piko-system'))){throw 'Unexpected Sunlogin persistent data directory'}
Assert-Plain $Data
$null=[IO.Directory]::CreateDirectory($Data)
$journal=Join-Path $Data 'piko-sunlogin-service.json'
foreach($p in @($journal,($journal+'.tmp'),($journal+'.bak'))){Assert-Plain $p}
$installer=$null
$outer=Join-Path $Root 'AweSun.exe'
$persistent=Join-Path (Split-Path -Parent $Data) 'AweSun\config.ini'
$config=Join-Path $Root 'AweSun\config.ini'
$names=@('AweSunService','SunloginService');
function Image([string]$command){
 if($command -match '^"([^"\r\n]+\.exe)"(?:\s+[^"\r\n]*)?$'){$p=$Matches[1]}
 elseif($command -match '^([^\s"\r\n]+\.exe)(?:\s+[^"\r\n]*)?$'){$p=$Matches[1]}
 else{throw ('Ambiguous service image: '+$command)}
 if($p -notmatch '^[A-Za-z]:\\' -or $p -match '%|\.\.'){throw 'Service image must be an absolute, unambiguous local path'}
 Full $p
}
function Owner($svc){
 if($svc.Name -cnotin $names){throw 'Unexpected service name'}
 $image=Image $svc.PathName
 if(!(Under $image $package)){throw ('External Sunlogin service retained: '+$svc.Name)}
 $relative=$image.Substring($package.Length+1)
 if($relative -notmatch '^([^\\]+)\\AweSun\\(AweSun|OldAweSun)\.exe$'){throw 'Unrecognized Sunlogin service layout'}
 $version=$Matches[1];$leaf=$Matches[2]+'.exe'
 $dir=Join-Path $package $version
 if($version -ieq 'current'){
  # current is the sole allowed alias: resolve exactly once, then require an
  # ordinary sibling version with a matching Piko installation receipt.
  $link=Get-Item -LiteralPath $dir -Force
  $targets=@($link.Target)
  if(!($link.Attributes -band [IO.FileAttributes]::ReparsePoint) -or $targets.Count -ne 1){throw 'Cannot prove legacy current service ownership'}
  $target=[string]($targets[0])
  if(![IO.Path]::IsPathRooted($target)){$target=Join-Path $package $target}
  $dir=Full $target
 }
 $dir=Full $dir
 $r=Read-Install $dir
 if($r.key -cne $install.key -or $r.source.identity -cne $install.source.identity){throw 'Sunlogin service belongs to another package source'}
 # Do not reject current before resolution, but reject every reparse point in
 # its real target, including a linked AweSun directory or executable.
 $realImage=Join-Path (Join-Path $dir 'AweSun') $leaf
 Assert-Plain $realImage
 [pscustomobject]@{name=$svc.Name;image=$image;realImage=$realImage;root=$dir;id=$r.id;checksum=$r.checksum}
}
function Services{@(Get-CimInstance Win32_Service -Filter "Name='AweSunService' OR Name='SunloginService'")}
function Inventory{@(Services|ForEach-Object{Owner $_})}
function Same($now,$prior){$now.image -ieq $prior.image -and $now.root -ieq $prior.root -and $now.id -ceq $prior.id -and $now.checksum -ceq $prior.checksum}
function Save([string]$state,[object[]]$owned,[string]$errorText=''){
 $value=@{schemaVersion=2;root=$Root;key=$install.key;identity=$install.source.identity;state=$state;services=@($owned);installer=$installer;error=$errorText;updated=[DateTime]::UtcNow.ToString('o')}
 $tmp=$journal+'.tmp'
 $value|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $tmp -Encoding UTF8
 if(Test-Path -LiteralPath $journal){
  $backup=$journal+'.bak'
  Remove-Item -LiteralPath $backup -Force -ErrorAction SilentlyContinue
  [IO.File]::Replace($tmp,$journal,$backup)
  Remove-Item -LiteralPath $backup -Force -ErrorAction SilentlyContinue
 }else{[IO.File]::Move($tmp,$journal)}
}
function Control([string]$operation,[string]$name){
 $null=& sc.exe $operation $name
 if($LASTEXITCODE -ne 0){throw ('Failed to '+$operation+' service: '+$name)}
}
function Await-Service([string]$name,[string]$state){
 $deadline=(Get-Date).AddSeconds(30)
 do{
  $s=@(Services|Where-Object Name -eq $name)
  if($state -eq 'absent' -and !$s.Count){return}
  if($s.Count -and $s[0].State -eq $state){return}
  Start-Sleep -Milliseconds 250
 }while((Get-Date) -lt $deadline)
 throw ('Service did not reach '+$state+': '+$name)
}
function Stop-Owned([object[]]$owned){
 foreach($o in $owned){
  $s=@(Services|Where-Object Name -eq $o.name)
  if(!$s.Count){continue}
  if(!(Same (Owner $s[0]) $o)){throw 'Service ownership changed before stop'}
  if($s[0].State -ne 'Stopped'){Control 'stop' $o.name;Await-Service $o.name 'Stopped'}
 }
}
function Assert-Idle([string]$dir){
 foreach($s in Services){
  $o=Owner $s
  if($o.root -ieq $dir -and $s.State -ne 'Stopped'){throw ('Stop Sunlogin before preserving service data: '+$s.Name)}
 }
}
function Snapshot([string]$dir){
 Assert-Idle $dir
 $tree=Join-Path $dir 'AweSun'
 if(!(Test-Path -LiteralPath $tree)){return}
 Assert-Plain $tree
 $stack=New-Object 'Collections.Generic.Stack[string]'
 $stack.Push($tree)
 while($stack.Count){
  $directory=$stack.Pop()
  foreach($entry in @(Get-ChildItem -LiteralPath $directory -Force)){
   if($entry.Attributes -band [IO.FileAttributes]::ReparsePoint){throw ('Cannot back up linked service data: '+$entry.FullName)}
   if($entry.PSIsContainer){$stack.Push($entry.FullName)}
  }
 }
 $backup=Join-Path (Join-Path $Data 'backups') ([IO.Path]::GetFileName($dir)+'-'+[Guid]::NewGuid().ToString('N'))
 Assert-Plain $backup
 $null=[IO.Directory]::CreateDirectory($backup)
 Copy-Item -LiteralPath $tree -Destination (Join-Path $backup 'AweSun') -Recurse -Force
 Assert-Idle $dir
 Assert-Plain $persistent
 if(Test-Path -LiteralPath $persistent -PathType Leaf){Copy-Item -LiteralPath $persistent -Destination (Join-Path $backup 'previous-persistent-config.ini')}
 # Only complete, stopped-service copies get this marker. Partial backups are
 # left intact on failure, but never advertised as complete or used for restore.
 [IO.File]::WriteAllText((Join-Path $backup 'complete.json'),(@{root=$dir;completed=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json))
 Write-Output ('Preserved Sunlogin service data: '+$backup)
}
function Publish-Config([string]$dir){
 Assert-Idle $dir
 $source=Join-Path $dir 'AweSun\config.ini'
 Assert-Plain $source;Assert-Plain $persistent
 $null=[IO.Directory]::CreateDirectory((Split-Path -Parent $persistent))
 if(Test-Path -LiteralPath $source -PathType Leaf){
  if(!(Test-Path -LiteralPath $persistent) -or (Digest $source) -cne (Digest $persistent)){[IO.File]::Copy($source,$persistent,$true)}
 }
}
function Link-Config{
 Assert-Idle $Root
 Assert-Plain $persistent;Assert-Plain $config
 $null=[IO.Directory]::CreateDirectory((Split-Path -Parent $persistent))
 $null=[IO.Directory]::CreateDirectory((Split-Path -Parent $config))
 if(!(Test-Path -LiteralPath $persistent)){
  if(Test-Path -LiteralPath $config -PathType Leaf){[IO.File]::Copy($config,$persistent,$false)}else{[IO.File]::WriteAllText($persistent,'')}
 }
 # Both the old config and the persistent config have already been backed up.
 # A vendor atomic replacement breaks a pre-existing hardlink; rebuild it while
 # stopped and fail with a recovery receipt if the filesystem cannot support it.
 if(Test-Path -LiteralPath $config){[IO.File]::Delete($config)}
 $null=New-Item -ItemType HardLink -Path $config -Target $persistent -ErrorAction Stop
 if((Digest $config) -cne (Digest $persistent)){throw 'Service configuration hardlink repair failed'}
}
function Clean([object[]]$owned){
 # Stop every service before copying a shared vendor tree, not one at a time.
 Stop-Owned $owned
 $dirs=@($owned|ForEach-Object{$_.root}|Select-Object -Unique)
 foreach($dir in $dirs){Snapshot $dir;Publish-Config $dir}
 foreach($o in $owned){
  $s=@(Services|Where-Object Name -eq $o.name)
  if(!$s.Count){continue}
  if(!(Same (Owner $s[0]) $o) -or $s[0].State -ne 'Stopped'){throw 'Service ownership/state changed before deletion'}
  Control 'delete' $o.name
  Await-Service $o.name 'absent'
 }
}
$record=$null
if(Test-Path -LiteralPath $journal){
 $record=Get-Content -LiteralPath $journal -Raw|ConvertFrom-Json
 if($record.schemaVersion -notin @(1,2) -or $record.state -notin @('installed','installing','recovery','cleanup-pending')){throw 'Unsupported Sunlogin service receipt'}
 $recordRoot=Full $record.root
 $recordInstall=Read-Install $recordRoot
 if($recordInstall.key -cne $install.key -or $recordInstall.source.identity -cne $install.source.identity){throw 'Service receipt belongs to another package source'}
 if($record.schemaVersion -eq 2 -and ($record.key -cne $install.key -or $record.identity -cne $install.source.identity)){throw 'Foreign Sunlogin service receipt'}
}
# Preflight the complete inventory before touching any service or journal.
$owned=@(Inventory)
$mine=@($owned|Where-Object root -ieq $Root)
if($Action -eq 'remove' -and (($record -and $recordRoot -ine $Root) -or (!$record -and $owned.Count -and !$mine.Count))){
 if($mine.Count){throw 'Candidate has a service conflicting with another version receipt'}
 # Removing an unselected candidate must preserve the active service, its receipt
 # bytes and its shared configuration. Back up only this candidate's local data.
 Snapshot $Root
 Write-Output 'Preserved candidate data; another version service and receipt were not changed'
 return
}
if($record -and $recordRoot -ine $Root){throw 'Another Piko version owns the Sunlogin receipt; remove that version first'}
if($record -and $record.installer){
 $active=Get-Process -Id $record.installer.pid -ErrorAction SilentlyContinue
 if($active -and $active.StartTime.ToUniversalTime().ToString('o') -eq $record.installer.started){throw 'Vendor installer still running; wait for it to exit before retrying'}
}
if($record -and $record.schemaVersion -eq 2){
 foreach($o in $owned){
  $prior=@($record.services|Where-Object name -eq $o.name)
  if($prior.Count -and !(Same $o $prior[0])){throw 'Service no longer matches its ownership receipt'}
 }
}
Save 'recovery' $owned
try{
 Clean $owned
 if($Action -eq 'remove'){
  Snapshot $Root
  if($mine.Count -or ($record -and $record.state -in @('installed','installing','cleanup-pending'))){Publish-Config $Root}
  Remove-Item -LiteralPath $journal
  Write-Output 'Removed owned Sunlogin service registration; persistent data and backups retained'
  return
 }
 if(!(Test-Path -LiteralPath $outer -PathType Leaf)){throw 'Outer AweSun.exe missing from this version directory'}
 Assert-Plain $outer
 Snapshot $Root
 Link-Config
 Save 'installing' @()
 $proc=Start-Process -FilePath $outer -ArgumentList @('--mod=install','--admin=1','--cmd=install_silent','--serviceonly=1',('--path="'+$Root+'"')) -PassThru
 if(!$proc.HasExited){$installer=@{pid=$proc.Id;started=$proc.StartTime.ToUniversalTime().ToString('o')};Save 'installing' @()}
 $deadline=(Get-Date).AddSeconds(180)
 $ok=$false
 do{
  Start-Sleep -Seconds 3
  $observed=@(Inventory)
  foreach($o in $observed){if($o.root -ine $Root -or !(Under $o.image $Root)){throw 'Vendor installer registered a service outside this real version'}}
  Save 'installing' $observed
  $service=@(Services|Where-Object Name -eq 'AweSunService')
  if($service.Count -and $service[0].State -eq 'Running'){$ok=$true;break}
  if($proc.HasExited -and $proc.ExitCode -ne 0){throw ('Vendor service installer failed with exit code '+$proc.ExitCode)}
 }while((Get-Date) -lt $deadline)
 if(!$ok){throw 'Vendor service installer did not reach a running AweSunService under this version directory'}
 if(!$proc.WaitForExit(15000)){throw 'Vendor installer still running; retain receipt and retry after it exits'}
 if($proc.ExitCode -ne 0){throw ('Vendor service installer failed with exit code '+$proc.ExitCode)}
 $installer=$null
 # The installer may replace config.ini atomically. Stop every owned service,
 # snapshot a consistent tree, publish the resulting config and repair its link
 # before restarting. Never copy live service databases to a claimed backup.
 $restart=@(Services|Where-Object State -eq 'Running'|ForEach-Object{$_.Name})
 $observed=@(Inventory)
 Stop-Owned $observed
 Snapshot $Root
 Publish-Config $Root
 Link-Config
 foreach($name in $restart){
  $s=@(Services|Where-Object Name -eq $name)
  $prior=@($observed|Where-Object name -eq $name)
  if(!$s.Count -or !$prior.Count -or !(Same (Owner $s[0]) $prior[0])){throw 'Service ownership changed before restart'}
  Control 'start' $name;Await-Service $name 'Running'
 }
 $final=@(Inventory)
 foreach($o in $final){if($o.root -ine $Root -or !(Under $o.image $Root)){throw 'Service escaped this version during restart'}}
 $service=@(Services|Where-Object Name -eq 'AweSunService')
 if(!$service.Count -or $service[0].State -ne 'Running'){throw 'AweSunService did not remain running after data preservation'}
 Save 'installed' $final
 Write-Output 'Installed version-anchored Sunlogin service registration'
}catch{
 $failure=$_.Exception.Message
 $last=Get-Content -LiteralPath $journal -Raw|ConvertFrom-Json
 Save 'cleanup-pending' @($last.services) $failure
 throw
}
